exercises.solution:
from sklearn.datasets import load_wine
from sklearn.decomposition import PCA


def reduced_shape(k):
    X = load_wine().data
    Xs = (X - X.mean(axis=0)) / X.std(axis=0)
    return list(PCA(n_components=k).fit_transform(Xs).shape)
